import React from 'react';

export const FieldsIcon = ({ color, height, width, fontsize }) => {
    const styles = {
        color: color || '#ffffff',
        height: height || '1em',
        width: width || '1em',
        fontSize: fontsize || '32px',
    };
    return (
        <svg
            xmlns="http://www.w3.org/2000/svg"
            style={styles}
            version="1.2"
            viewBox="0 0 512 512"
        >
            <defs>
                <image
                    id="img1"
                    width="512"
                    height="512"
                    href="data:image/png;base64,"
                ></image>
            </defs>
            <style></style>
            <use id="Calque 1" x="0" y="0" href="#img1"></use>
        </svg>
    );
}

